INSERT INTO kb_articles (id, category_id, slug, status, is_featured, is_public, reading_time_minutes, thumbnail_url, related_modules, target_audience, created_at, updated_at) VALUES
  ('kb-consultify-06_scenario_planning', 'kb-cat-consultify-decisions-that-ship', '06_scenario_planning', 'published', 1, 1, 5, '/kb/consultify/06_scenario_planning/hero.png', '["assessment","dashboard","roadmap"]', '["Owner / President / CFO"]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
